OUT=ROOT/'geometry-course/textbook/data/homothetic-grid-figures.json'
CAP='Один отрезок UW соответствует одной клетке. Штрих обозначает образ. Во второй и третьей моделях можно проверить разные этапы построения.'


def at(x,y,k,o):return (o[0]+k*(x-o[0]),o[1]+k*(y-o[1]))


def polygons(title,vertices,center,k,center_name=None):
    name=center_name or 'T'
    pts={name:center,**vertices};pts.update({n+'′':at(*p,k,center) for n,p in vertices.items()})
    order=list(vertices);sides=[]
    for suffix in ('','′'):
        sides.extend((x+suffix,y+suffix) for x,y in zip(order,order[1:]+order[:1]))
    # Internal X/Y are reserved for coordinate axes by the shared planar viewer.
    alias={key:('vertex'+key if key in ('X','Y','X′','Y′') else key) for key in pts}
    return diagram(title,{alias[k]:p for k,p in pts.items()},[(alias[a],alias[b]) for a,b in sides])


def triangles(part):
    if part=='а':
        a={'A':(-3,0),'B':(0,3),'C':(3,0)};o=(0,1.5);k=3;center='T'
        scenes=[polygons('Исходный рисунок 401а и образ',a,o,k),polygons('Проверь основание A′C′',a,o,k),polygons('Новый треугольник с основанием 4',{'A':(-2,0),'B':(0,2),'C':(2,0)},(0,1),k)]
        label='ABC с центром O и коэффициентом 3';proof='T изображает точку O. На исходной сетке основания AC=6, высота из B равна 3, O лежит на высоте в 1,5 клетки от основания. На лучах OA, OB, OC откладываем втрое большие расстояния и соединяем A′,B′,C′. Если принять середину AC за (0,0), то A′=(−9,−3), B′=(0,6), C′=(9,−3).'
        steps=[('Установи центр по рисунку','O лежит внутри ABC на его высоте, между горизонталями сетки. Используй расстояние 1,5 клетки от основания, когда отмеряешь образы вершин.','Перенос центра на ближайшее целое пересечение изменит все три образа.'),
               ('Проверь основание','Расстояния между образами тоже утраиваются. Найди длину A′C′, если AC=6 клеток.','Коэффициент касается любой пары точек, а не только расстояния от центра.'),
               ('Повтори с новым основанием','На третьей схеме исходное основание равно 4 клеткам. Проверь построение через длину нового основания.','У третьей модели свои исходные размеры, коэффициент остался равным 3.')];checks=[('Сколько клеток в A′C′ для печатного рисунка?','18','6·3=18.'),('Чему равно основание образа в новом примере?','12','4·3=12.')]
    elif part=='б':
        a={'X':(-4,-2),'Y':(-1,-5),'Z':(0,0)};o=a['Z'];k=.5;center='Z'
